"""
certifi.py
~~~~~~~~~~

This module returns the installation location of cacert.pem or its contents.

conda-forge: the bundled cacert.pem is removed and the CA bundle provided by
the ca-certificates package is used instead.
"""
import os
import sys


def where() -> str:
    if sys.platform == "win32":
        path = os.path.join(sys.base_prefix, "Library", "ssl", "cacert.pem")
        if os.path.isfile(path):
            return path
    return os.path.join(sys.base_prefix, "ssl", "cacert.pem")


def contents() -> str:
    with open(where(), encoding="ascii") as f:
        return f.read()
